const data = $json.body ?? $json;
const name=String(data.name??'').trim();
const email=String(data.email??'').trim().toLowerCase();
const company=String(data.company??'').trim();
const message=String(data.message??'').trim();
const budget=Number(data.budget??0);
const source=String(data.source??'Website').trim()||'Website';
if(!name) throw new Error('Lead name is required');
if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('Valid email is required');
if(!message) throw new Error('Lead message is required');
if(!Number.isFinite(budget)||budget<0) throw new Error('Budget must be a valid non-negative number');
return [{json:{name,email,company,message,budget,source,received_at:new Date().toISOString()}}];

const lead=$('Validate Lead').first().json;
const rows=$input.all().map(i=>i.json).filter(r=>r&&typeof r==='object');
const duplicate=rows.some(r=>String(r.Email??r.email??'').trim().toLowerCase()===lead.email);
return [{json:{...lead,duplicate}}];

