const lead=$('Validate Lead').first().json;
const raw=$json.message?.content??$json.content??$json.text??'';
if(!raw) throw new Error('AI response was empty');
const cleaned=String(raw).trim().replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/i,'');
let a; try{a=JSON.parse(cleaned)}catch{throw new Error('AI returned invalid JSON')}
if(typeof a.qualified!=='boolean') throw new Error('AI qualified must be boolean');
const score=Number(a.score); if(!Number.isFinite(score)||score<0||score>100) throw new Error('AI score must be 0-100');
const priority=String(a.priority??'').toLowerCase(); if(!['high','medium','low'].includes(priority)) throw new Error('Invalid AI priority');
return [{json:{...lead,qualified:a.qualified,score,priority,reason:String(a.reason??''),service_needed:String(a.service_needed??''),recommended_action:String(a.recommended_action??''),status:a.qualified?'Qualified':'Nurture'}}];

